INSERT INTO public.bcps_iidl_units (slug, name, summary, page_url, sort_order) VALUES ('ai-digital-citizenship', 'Artificial Intelligence & Digital Citizenship', NULL, NULL, 1) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.bcps_iidl_services (name, unit_slug, description, contact_name, contact_title, contact_email, contact_phone, contact_address, booking_url, booking_note, audience, service_url, review_note, sort_order) VALUES
('3D Printing, Spatial Reasoning & Design Thinking', 'stem-computer-science', 'Designing and creating 3D manipulatives and tools using Tinkercad and 3D printing.', 'Dr. Lisa Milenkovic', 'Supervisor, STEM+C, AI, & Immersive Learning', 'lisa.milenkovic@browardschools.com; browardstem@browardschools.com', '754-321-1880, 754-321-2623', NULL, 'https://bookings.cloud.microsoft/book/BrowardSTEMCS@browardcountyschools.onmicrosoft.com/?ismsaljsauthenabled=true', NULL, 'school', NULL, NULL, 1),
('Adobe Express', 'instructional-technology', 'Creative platform that enable educators and students to create presentations, graphics, videos, digital stories, and multimedia learning products.', NULL, NULL, NULL, NULL, NULL, 'https://bookings.cloud.microsoft/book/InnovativeLearningDepartment@browardcountyschools.onmicrosoft.com/?ismsaljsauthenabled=true', 'This is an open session for teachers who have questions regarding Adobe Express and need assistance.', 'school', NULL, NULL, 2),
('AI Learning Pathways (Coming Soon)', 'professional-learning', 'Coming soon: structured learning pathways to support educators at different levels of AI knowledge and experience. Registration details will be shared when available.', 'Monica Bianchi', 'Supervisor, Professional Learning', 'lab@browardschools.com', '754-321-5055', NULL, NULL, NULL, 'all', NULL, NULL, 3),
('AI Liaison Support', 'ai-digital-citizenship', 'School-based instructional champions who provide peer support, classroom modeling, and practical guidance to help teachers, staff, students, and families use district-approved AI tools responsibly and effectively.', 'Claudia Brites', 'Project Manager, Technology & Support', 'claudia.brites@browardschools.com', NULL, NULL, NULL, NULL, 'school', NULL, NULL, 4),
('AI Staff Hub', 'professional-learning', 'Provides a central location for practical guidance, strategies, and implementation resources for using BCPS-approved AI tools, with role-specific resources for instructional staff, school leaders, district administrators, and AI Liaisons. Access it through Clever, the Resources and Help menu in Canvas, or the enrollment link: https://browardschools.instructure.com/enroll/3LJAXT', 'Monica Bianchi', 'Supervisor, Professional Learning', 'lab@browardschools.com', '754-321-5055', NULL, NULL, NULL, 'all', NULL, NULL, 5),
('BCPS EcoGuide', 'stem-computer-science', 'Resources for environmental initiatives, programs, lesson plans, activities, and contacts for teachers, staff and students', 'Dr. Lisa Milenkovic', 'Supervisor, STEM+C, AI, & Immersive Learning', 'lisa.milenkovic@browardschools.com; browardstem@browardschools.com', '754-321-1880, 754-321-2623', NULL, 'https://bookings.cloud.microsoft/book/BrowardSTEMCS@browardcountyschools.onmicrosoft.com/?ismsaljsauthenabled=true', NULL, 'school', 'https://www.browardschools.com/bcps-departments/academics/instructional-innovation-digital-learning/stem-and-computer-science-programs/environmental-stewardship/bcps-ecoguide', NULL, 6),
('Beanstack', 'library-media-services', 'Supports reading progress tracking, engaging challenges, achievement badges, and classroom library success.', NULL, NULL, NULL, NULL, NULL, 'https://bookings.cloud.microsoft/book/InnovativeLearningDepartment@browardcountyschools.onmicrosoft.com/?ismsaljsauthenabled=true', 'Beanstack Support covers generating challenges, generating reports, and analytics for Media Specialists or other Instructional personnel assigned as the Beanstack administrator.', 'school', NULL, NULL, 7),
('Broward Virtual University (BVU) & Endorsement Courses', 'professional-learning', 'Online endorsement coursework for eligible BCPS and external educators, with support for registration, course participation, and completion.', 'Monica Bianchi', 'Supervisor, Professional Learning', 'bvu@browardschools.com', '754-321-5053', NULL, NULL, NULL, 'all', NULL, NULL, 8),
('#BrowardCODES, AI Literacy & Computer Science', 'stem-computer-science', 'Curriculum integration resources for AI, computer science, computational thinking, and data science. Includes resources for Hour of AI and Day of AI. Includes UDL4CS program to provide specific strategies to support ESE students.', 'Dr. Lisa Milenkovic', 'Supervisor, STEM+C, AI, & Immersive Learning', 'lisa.milenkovic@browardschools.com; browardstem@browardschools.com', '754-321-1880, 754-321-2623', NULL, 'https://bookings.cloud.microsoft/book/BrowardSTEMCS@browardcountyschools.onmicrosoft.com/?ismsaljsauthenabled=true', NULL, 'school', NULL, NULL, 9),
('Canvas Learning Management System (LMS)', 'instructional-technology', 'The district learning management system for organizing courses, sharing resources, communicating with students, and supporting digital instruction both in and beyond the classroom.', 'BCPS Canvas Admin', NULL, 'bcpscanvasadmin@browardschools.com', NULL, NULL, 'https://bookings.cloud.microsoft/book/InnovativeLearningDepartment@browardcountyschools.onmicrosoft.com/?ismsaljsauthenabled=true', 'This is an open session for teachers who have questions regarding Canvas or any of the integrations and need assistance.', 'school', NULL, NULL, 10),
('Classwize Training Support', 'instructional-technology', 'Training support for teachers with the use of the Classwize Linewize classroom device management program.', 'Jaclyn Sherman', 'Professional Development Specialist', 'jaclyn.sherman@browardschools.com', NULL, NULL, 'https://bookings.cloud.microsoft/book/InnovativeLearningDepartment@browardcountyschools.onmicrosoft.com/?ismsaljsauthenabled=true', 'This is an open session for teachers who have questions regarding Classwize and need integration assistance. For technical issues, please reach out to the IT Help Desk.', 'school', NULL, NULL, 11),
('Curriculum Implementation', 'instructional-digital-materials', 'Planning tools and instructional supports that help educators use adopted materials effectively and confidently.', 'Nathan Clock', 'Instructional & Digital Materials Analyst', 'nathan.clock@browardschools.com', '754-321-2646', '600 SE Third Avenue, Fort Lauderdale, FL 33301', NULL, NULL, 'school', NULL, NULL, 12),
('Destiny', 'library-media-services', 'Provides access to the district’s print and digital library catalog through a user friendly library management platform.', NULL, NULL, NULL, NULL, NULL, 'https://bookings.cloud.microsoft/book/InnovativeLearningDepartment@browardcountyschools.onmicrosoft.com/?ismsaljsauthenabled=true', 'Destiny support covers all aspects of Destiny for Media Specialists, teachers, and Media Clerks.', 'school', NULL, NULL, 13),
('Destiny Resource Manager (DRM)', 'instructional-digital-materials', 'Access point for textbook coordinators for inventory management', 'Nathan Clock', 'Instructional & Digital Materials Analyst', 'nathan.clock@browardschools.com', '754-321-2646', NULL, 'https://bookings.cloud.microsoft/book/InnovativeLearningDepartment@browardcountyschools.onmicrosoft.com/?ismsaljsauthenabled=true', 'Destiny Resource Manager (DRM) Support can answer questions regarding adding assets to the DRM platform and barcoding.', 'school', NULL, NULL, 14),
('Distance Learning', 'distance-learning', 'Learning opportunities that transform the classroom into a gateway for exploration, collaboration, and global engagement.', 'Tamika Nelms', 'Distance Learning Outreach Specialist', 'tamika.nelms@browardschools.com', '754-321-1013', NULL, 'https://bookings.cloud.microsoft/book/InnovativeLearningDepartment@browardcountyschools.onmicrosoft.com/?ismsaljsauthenabled=true', 'This is an open session for teachers who have questions regarding Distance Learning and need assistance.', 'school', NULL, NULL, 15),
('District Professional Learning Calendar & Scheduling', 'professional-learning', 'District professional learning calendar and scheduling guidance, including designated dates and restrictions that schools and departments must consider when planning learning.', 'Monica Bianchi', 'Supervisor, Professional Learning', 'lab@browardschools.com', '754-321-5055', NULL, NULL, NULL, 'all', NULL, NULL, 16),
('District-Approved Resources', 'instructional-digital-materials', 'Reviewed resources and digital content that align with district expectations and support classroom instruction.', 'Nathan Clock', 'Instructional & Digital Materials Analyst', 'nathan.clock@browardschools.com', '754-321-2646', '600 SE Third Avenue, Fort Lauderdale, FL 33301', NULL, NULL, 'all', NULL, NULL, 17),
('Drones and SeaPerch ROV', 'stem-computer-science', 'Flying (drones) and underwater (SeaPerch) remote vehicle problem-solving, hands-on competitions.', 'Dr. Lisa Milenkovic', 'Supervisor, STEM+C, AI, & Immersive Learning', 'lisa.milenkovic@browardschools.com; browardstem@browardschools.com', '754-321-1880, 754-321-2623', NULL, 'https://bookings.cloud.microsoft/book/BrowardSTEMCS@browardcountyschools.onmicrosoft.com/?ismsaljsauthenabled=true', NULL, 'school', NULL, NULL, 18),
('Educational Partnerships', 'distance-learning', 'Collaborations with educational organizations that provide meaningful virtual learning experiences and resources.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'school', NULL, NULL, 19),
('Esports (Minecraft, Rocket League, others)', 'stem-computer-science', 'Competitive video gaming clubs support application of STEM within a team structure.', 'Dr. Lisa Milenkovic', 'Supervisor, STEM+C, AI, & Immersive Learning', 'lisa.milenkovic@browardschools.com; browardstem@browardschools.com', '754-321-1880, 754-321-2623', NULL, 'https://bookings.cloud.microsoft/book/BrowardSTEMCS@browardcountyschools.onmicrosoft.com/?ismsaljsauthenabled=true', NULL, 'school', NULL, NULL, 20),
('Expert Connections', 'distance-learning', 'Virtual sessions that bring authors, scientists, industry professionals, and subject matter experts directly into classrooms.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'school', NULL, NULL, 21),
('Gale', 'library-media-services', 'Offers extensive research databases, reliable academic content, and instructional resources for students and educators.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'school', NULL, NULL, 22),
('Gardens: Edible, Food Forest, Butterfly', 'stem-computer-science', 'Support for using the outdoor campus environment for learning.', 'Dr. Lisa Milenkovic', 'Supervisor, STEM+C, AI, & Immersive Learning', 'lisa.milenkovic@browardschools.com; browardstem@browardschools.com', '754-321-1880, 754-321-2623', NULL, 'https://bookings.cloud.microsoft/book/BrowardSTEMCS@browardcountyschools.onmicrosoft.com/?ismsaljsauthenabled=true', NULL, 'school', NULL, NULL, 23),
('Global Learning Opportunities', 'distance-learning', 'Experiences that expose students to diverse perspectives, cultures, and real-world learning beyond their local community.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'school', NULL, NULL, 24),
('Inservice Credit & Transcript Support', 'professional-learning', 'Assistance with missing or incorrect inservice credit, transcript discrepancies, and questions about recorded professional learning completions.', 'Monica Bianchi', 'Supervisor, Professional Learning', 'lab@browardschools.com', '754-321-5055', NULL, NULL, NULL, 'all', NULL, NULL, 25),
('Instructional Technology Facilitators (ITFs)', 'instructional-technology', 'Provide coaching, modeling, and professional learning, and implementation support to help educators effectively integrate technology into teaching and learning.', 'Jaclyn Sherman', 'Professional Development Specialist', 'jaclyn.sherman@browardschools.com', NULL, NULL, 'https://bookings.cloud.microsoft/book/InnovativeLearningDepartment@browardcountyschools.onmicrosoft.com/?ismsaljsauthenabled=true', 'This service is for teachers who need support from the Instructional Technology Facilitator assigned to your school. When selecting the staff, be sure to select the ITF you have been working with this year.', 'school', NULL, NULL, 26),
('Interactive Videoconferencing', 'distance-learning', 'Live virtual connections that extend beyond the classroom and support authentic learning experiences.', NULL, NULL, NULL, NULL, NULL, 'https://bookings.cloud.microsoft/book/InnovativeLearningDepartment@browardcountyschools.onmicrosoft.com/?ismsaljsauthenabled=true', NULL, 'school', NULL, 'Rev10 booking note describes Interactive Whiteboard support (ActivInspire, ClassFlow, Xpress), not videoconferencing, so it is hidden. Correct booking note needed from II&DL.', 27),
('Learning Across Broward (LAB) Administration & Support', 'professional-learning', 'Support for accessing LAB, registering for courses, checking completion status, and accessing professional learning transcripts.', 'Monica Bianchi', 'Supervisor, Professional Learning', 'lab@browardschools.com', '754-321-5055', NULL, NULL, NULL, 'all', NULL, NULL, 28),
('Library Programming Support', 'library-media-services', 'Personalized support for library programming, including collection development, compliance, budgeting, digital resources, makerspaces, literacy initiatives, and overall library program planning.', 'Celia Taylor', 'Curriculum Supervisor, Library Media', 'celia.taylor@browardschools.com', '754-321-1867', NULL, 'https://bookings.cloud.microsoft/book/InnovativeLearningDepartment@browardcountyschools.onmicrosoft.com/?ismsaljsauthenabled', 'Library Program support covers building the library collection, acquisition, budgeting, ordering, Inquiry-Based Lesson Design, access and layout, collaboration with colleagues, etc. for Media Specialists and Media clerks.', 'school', NULL, NULL, 29),
('M365 Learning Accelerators Support', 'instructional-technology', 'Provide coaching, modeling, and professional learning, and implementation support to help educators effectively integrate Learning Accelerators into teaching and learning.', 'Jaclyn Sherman', 'Professional Development Specialist', 'jaclyn.sherman@browardschools.com', NULL, NULL, 'https://bookings.cloud.microsoft/book/InnovativeLearningDepartment@browardcountyschools.onmicrosoft.com/?ismsaljsauthenabled=true', 'This is an open session for teachers who have questions regarding Microsoft Learning Accelerators such as Reading Progress and need assistance.', 'school', NULL, NULL, 30),
('M365 Productivity Applications Support', 'instructional-technology', 'Provide coaching, professional learning, and implementation support for teachers who have questions regarding Word, PowerPoint, Class Notebook, Excel, or any other applications found in the M365 Suite.', 'Jaclyn Sherman', 'Professional Development Specialist', 'jaclyn.sherman@browardschools.com', NULL, NULL, 'https://bookings.cloud.microsoft/book/InnovativeLearningDepartment@browardcountyschools.onmicrosoft.com/?ismsaljsauthenabled=true', 'This is an open session for teachers who have questions regarding Word, PowerPoint, Class Notebook, Excel, or any other applications found in the M365 and need assistance.', 'school', NULL, NULL, 31),
('MagicSchool AI', 'instructional-technology', 'Artificial intelligence powered tool that supports lesson planning, differentiation, assessment creation, instructional resource development, and student-centered learning experiences.', NULL, NULL, NULL, NULL, NULL, 'https://bookings.cloud.microsoft/book/InnovativeLearningDepartment@browardcountyschools.onmicrosoft.com/?ismsaljsauthenabled=true', 'This is an open session for teachers who have questions regarding Magic School and need assistance.', 'school', NULL, NULL, 32),
('Mandatory Compliance Learning & Monitoring', 'professional-learning', 'Coordinates mandatory compliance course assignments for district departments including completion tracking in LAB. Provides reports and dashboards that principals and district leaders use to monitor staff progress, identify incomplete training, and direct follow-up.', 'Monica Bianchi', 'Supervisor, Professional Learning', 'lab@browardschools.com', '754-321-5055', NULL, NULL, NULL, 'all', NULL, NULL, 33),
('Material Adoption Information', 'instructional-digital-materials', NULL, 'Nathan Clock', 'Instructional & Digital Materials Analyst', 'nathan.clock@browardschools.com', '754-321-2646', '600 SE Third Avenue, Fort Lauderdale, FL 33301', NULL, NULL, 'family', NULL, 'Rev10 Services Description is the Canvas LMS text copied onto this row ("Online spaces that help educators organize lessons..."), so it is hidden. Real description needed from II&DL.', 34),
('Microsoft 365 Productivity Applications Support', 'instructional-technology', 'Productivity, collaboration, and personalized learning tools that support communication, content creation, feedback, and student engagement.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'school', NULL, 'Looks like an older version of "M365 Productivity Applications Support" (same topic, no contact or booking). Confirm with II&DL whether both should stay.', 35),
('Mixed & Virtual Reality (AR/VR/XR, PrismsVR, ReframeXR)', 'stem-computer-science', 'Using the latest in extended reality devices and applications to remove the space and time constraints of reality with virtual manipulatives and field trips while in the physical classroom using XR technology.', 'Dr. Lisa Milenkovic', 'Supervisor, STEM+C, AI, & Immersive Learning', 'lisa.milenkovic@browardschools.com; browardstem@browardschools.com', '754-321-1880, 754-321-2623', NULL, 'https://bookings.cloud.microsoft/book/BrowardSTEMCS@browardcountyschools.onmicrosoft.com/?ismsaljsauthenabled=true', NULL, 'school', NULL, NULL, 36),
('Parent University/Town Hall Meetings Setup', 'distance-learning', 'Setup and coordinate live Teams Town Halls for district staff presenting important district information to the community', 'Patrick Phillips', 'Technical Support Analyst II', 'patrick.phillips@browardschools.com', '754-321-1084', NULL, NULL, NULL, 'school', NULL, NULL, 37),
('Partnerships with the STEM Community', 'stem-computer-science', 'Connections with the local STEM ecosystem (http://basestem.org) members including higher education, non-profit providers, and industries.', 'Dr. Lisa Milenkovic', 'Supervisor, STEM+C, AI, & Immersive Learning', 'lisa.milenkovic@browardschools.com; browardstem@browardschools.com', '754-321-1880, 754-321-2623', NULL, 'https://bookings.cloud.microsoft/book/BrowardSTEMCS@browardcountyschools.onmicrosoft.com/?ismsaljsauthenabled=true', NULL, 'school', NULL, NULL, 38),
('PebbleGo Next', 'library-media-services', 'Provides an interactive, student-friendly research database with engaging informational content for grades 3-5.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'school', NULL, NULL, 39),
('Poly Studio Video Bar Support', 'library-media-services', 'Provides support for teachers using Poly Studio Video Bar systems, including assistance with virtual learning and Microsoft Teams connections.', 'Celia Taylor', 'Curriculum Supervisor, Library Media', 'celia.taylor@browardschools.com', '754-321-1867', NULL, 'https://bookings.cloud.microsoft/book/InnovativeLearningDepartment@browardcountyschools.onmicrosoft.com/?ismsaljsauthenabled=true', 'This is an open session for teachers who have questions regarding Poly Studio Video Bar and need assistance.', 'school', NULL, NULL, 40),
('Professional Learning Planning & Compliance', 'professional-learning', 'Districtwide professional learning coordination, compliance guidance, catalog and Blueprint management, and evaluation to support quality and accountability.', 'Monica Bianchi', 'Supervisor, Professional Learning', 'monica.bianchi@browardschools.com; claudia.brites@browardschools.com', '754-321-5055', NULL, NULL, NULL, 'all', NULL, NULL, 41),
('Professional Learning Provider & Contact Support', 'professional-learning', 'Supports department PL Providers and Contacts in designing, proposing, documenting, and managing professional learning. Provides procedures and technical guidance for course setup, rosters, completion processing, and alignment with state and district requirements.', 'Monica Bianchi', 'Supervisor, Professional Learning', 'lab@browardschools.com', '754-321-5055', NULL, NULL, NULL, 'all', NULL, NULL, 42),
('Recycling, Compost, Climate Summit & P3 Eco-Challenge', 'stem-computer-science', 'Environmental stewardship curriculum resources and recognition programs.', 'Dr. Lisa Milenkovic', 'Supervisor, STEM+C, AI, & Immersive Learning', 'lisa.milenkovic@browardschools.com; browardstem@browardschools.com', '754-321-1880, 754-321-2623', NULL, 'https://bookings.cloud.microsoft/book/BrowardSTEMCS@browardcountyschools.onmicrosoft.com/?ismsaljsauthenabled=true', NULL, 'school', NULL, NULL, 43),
('Robotics', 'stem-computer-science', 'After school and in class robotics for competition and learning. Primarily integrating VEX robotics platform elementary - high school.', 'Dr. Lisa Milenkovic', 'Supervisor, STEM+C, AI, & Immersive Learning', 'lisa.milenkovic@browardschools.com; browardstem@browardschools.com', '754-321-1880, 754-321-2623', NULL, 'https://bookings.cloud.microsoft/book/BrowardSTEMCS@browardcountyschools.onmicrosoft.com/?ismsaljsauthenabled=true', NULL, 'school', NULL, NULL, 44),
('Sora', 'library-media-services', 'Provides convenient access to eBooks and audiobooks through a user-friendly platform with online and offline reading options.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'school', NULL, NULL, 45),
('STEM Challenges & Competitions', 'stem-computer-science', 'Quarterly independent asynchronous STEM challenges across a variety of real-world problem solving contexts and support for in school and afterschool STEM competition clubs such as SECME.', 'Dr. Lisa Milenkovic', 'Supervisor, STEM+C, AI, & Immersive Learning', 'lisa.milenkovic@browardschools.com; browardstem@browardschools.com', '754-321-1880, 754-321-2623', NULL, 'https://bookings.cloud.microsoft/book/BrowardSTEMCS@browardcountyschools.onmicrosoft.com/?ismsaljsauthenabled=true', NULL, 'school', NULL, NULL, 46),
('STEM Lending Library', 'stem-computer-science', 'STEM equipment available for teachers who attend the professional learning to borrow for use with their class and/or club students. Includes a variety of robotics, 3D printers, micro:bits and more for all grade levels.', 'Dr. Lisa Milenkovic', 'Supervisor, STEM+C, AI, & Immersive Learning', 'lisa.milenkovic@browardschools.com; browardstem@browardschools.com', '754-321-1880, 754-321-2623', NULL, 'https://bookings.cloud.microsoft/book/BrowardSTEMCS@browardcountyschools.onmicrosoft.com/?ismsaljsauthenabled=true', NULL, 'school', NULL, NULL, 47),
('Substitute Support', 'instructional-technology', 'This service is for Substitutes who need support from an Instructional Technology Facilitator.', 'Jaclyn Sherman', 'Professional Development Specialist', 'jaclyn.sherman@browardschools.com', NULL, NULL, 'https://bookings.cloud.microsoft/book/InnovativeLearningDepartment@browardcountyschools.onmicrosoft.com/?ismsaljsauthenabled=true', NULL, 'school', NULL, NULL, 48),
('Textbooks & eTextbooks', 'instructional-digital-materials', 'District-approved print and digital materials that support standards-aligned instruction and consistent access to core content.', NULL, NULL, NULL, NULL, NULL, 'https://bookings.cloud.microsoft/book/InnovativeLearningDepartment@browardcountyschools.onmicrosoft.com/?ismsaljsauthenabled=true', 'Textbook Coordinator Support', 'school', NULL, NULL, 49),
('VILS Support', 'instructional-technology', 'Helps educators use Apple devices and applications with purpose to strengthen instruction, personalize learning, and engage students.', 'Jaclyn Sherman', 'Professional Development Specialist', 'jaclyn.sherman@browardschools.com', NULL, NULL, 'https://bookings.cloud.microsoft/book/InnovativeLearningDepartment@browardcountyschools.onmicrosoft.com/?ismsaljsauthenabled=true', 'This is an open session for teachers from VILS schools who have questions and need assistance.', 'school', NULL, NULL, 50),
('Virtual Field Trips', 'distance-learning', 'Interactive learning experiences that connect students with experts and educational specialists from around the world through videoconferencing.', 'Tamika Nelms', 'Distance Learning Outreach Specialist', 'distancelearning@browardschools.com', NULL, NULL, 'https://bookings.cloud.microsoft/book/InnovativeLearningDepartment@browardcountyschools.onmicrosoft.com/?ismsaljsauthenabled=true', NULL, 'school', NULL, NULL, 51);
